```javascript
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Настройте токен вашего бота в следующей строке
client.config = {
  token: 'ВАШ_ТОКЕН_ДИСКОРДА',
};

// Функция для бана пользователя
async function banUser(guild, member, reason) {
  await guild.members.ban(member, { reason });
  return `Пользователь ${member.user.tag} был забанен из ${guild.name} с причиной: ${reason}`;
}

client.on('ready', () => {
  console.log(`Бот ${client.user.tag} готов к работе!`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName, member, channel } = interaction;

  if (commandName === 'ban') {
    if (!member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'У вас нет прав на банирование пользователей!',
        ephemeral: true,
      });
    }

    const userToBan = interaction.options.getUser('user');
    const reason = interaction.options.getString('reason', true);

    const guild = member.guild;

    try {
      const bannedUser = await banUser(guild, userToBan, reason);
      await interaction.reply({ content: bannedUser, ephemeral: true });
    } catch (error) {
      console.error(error);
      await interaction.reply({
        content: 'Произошла ошибка при выполнении команды. Пожалуйста, свяжитесь с администратором.',
        ephemeral: true,
      });
    }
  }
});

const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Банит пользователя')
  .addUserOption((option) =>
    option
      .setName('user')
      .setDescription('Пользователь, которого хотите забанить')
      .setRequired(true),
  )
  .addStringOption((option) =>
    option
      .setName('reason')
      .setDescription('Причина бана')
      .setRequired(true),
  );

client.on('ready', () => {
  client.application.commands.create({
    command: banCommand,
  });
});

client.login(client.config.token);
```

