std::string convertToHtml(const std::string& text_in_parens) {
    std::string html_text;
    std::stringstream ss(text_in_parens);

    std::string word;
    while (ss >> word) {
        if (word[0] == '\'' || word[0] == '"') {
            // Обработка кавычек
            html_text += "&" + (word[0] == '\'' ? "apos;" : "quot;") + ";";
        } else {
            // Обработка остальных символов
            for (char c : word) {
                html_text += "&#" + std::to_string(static_cast<unsigned int>(c)) + ";";
            }
        }
        html_text += " ";
    }

    return "<span class='text-in-parens'>" + html_text + "</span>";
}

std::string convertToHtml(const std::string& text) {
    std::string html_text;
    std::stringstream ss(text);

    std::string word;
    bool in_parens = false;
    while (ss >> word) {
        if (word == "(") {
            in_parens = true;
            html_text += "<span class='opening-paren'>";
        } else if (word == ")") {
            in_parens = false;
            html_text += "</span>";
        } else if (in_parens) {
            html_text += convertToHtml(word);
        } else {
            // Обработка остальных символов
            for (char c : word) {
                if (c == '\'' || c == '"') {
                    // Обработка кавычек
                    html_text += "&" + (c == '\'' ? "apos;" : "quot;") + ";";
                } else {
                    html_text += c;
                }
            }
        }
        html_text += " ";
    }

    return html_text;
}
